%[text] ## Introduction
%[text] In this project, the Healthy Dynamic PET (hedyPET) dataset containing \[F-18\]FDG dynamic PET/CT of 100 healthy humans was used (Hinge et al., 2026). The provided time-activity curves (TAC) as well as image-derived input functions (IDIF) in this dataset were used to calculate the net-influx rate (Ki) for the brain and spleen. MATLAB was used for all data processing and analysis.
%[text] Dataset source: https://doi.org/10.1038/s41597-026-08157-4
%%
%[text] ## Data loading
%[text] Load the provided TAC. Due to the large file size of the provided dataset, the necessary data have been pre-extracted for this project.
clearvars
clc
load TACData.mat;
load IDIF.mat;
load trueKi.mat;
%%
%[text] ## TAC data for brain and spleen
brainTACdata = sub000TACdata(string(sub000TACdata.("Label Name")) == "brain", :);
spleenTACdata = sub000TACdata(string(sub000TACdata.("Label Name")) == "spleen", :);
time = brainTACdata.("Frame Time Middle [s]");
brainAct = brainTACdata.("PET Mean [Bq/mL]");
spleenAct = spleenTACdata.("PET Mean [Bq/mL]");
plot(time,brainAct,'o') %[output:9b31c811]
title("Brain Activity Concentration vs. Time"); %[output:9b31c811]
xlabel("Time (min)"); %[output:9b31c811]
ylabel("Activity concentration (Bq/mL)"); %[output:9b31c811]
plot(time,spleenAct,'o') %[output:7c466c73]
xlabel("Time (min)"); %[output:7c466c73]
ylabel("Activity concentration (Bq/mL)"); %[output:7c466c73]
title("Spleen Activity Concentration vs. Time"); %[output:7c466c73]
%%
%[text] ## IDIF data
%[text] In the dataset, the Ki for a single organ was calculated using different IDIFs. In this project, the IDIF with  measured on the ascending Aorta with a 5-mm diameter cylinder and 3 mL volume (identifier: aortavois\_ml-full\_width-3\_ascending\_aorta) was used.
aortaAct = sub000IDIFdata.("PET Mean [Bq/mL]");
plot(time,aortaAct,'o') %[output:03bc7db6]
xlabel("Time (min)"); %[output:03bc7db6]
ylabel("Activity concentration (Bq/mL)"); %[output:03bc7db6]
title("Aorta Activity Concentration vs. Time"); %[output:03bc7db6]
%%
%[text] ## Estimation of net influx rate (Ki) using Patlak plot method
%[text] The Patlak plot equation is
%[text] $\\frac{C\\left(t\\right)}{\\mathrm{IDIF}\\left(t\\right)}=K\_i \\frac{\\;\\mathrm{IDIFTIAC}\\left(t\\right)}{\\;\\mathrm{IDIF}\\left(t\\right)}+V\_B${"editStyle":"visual"}
%[text] Where C(t) is the tracer concentration in tissue and IDIF(t) is the tracer concentration in blood.
%[text] The last eight frames will be used for calculation of Ki for a direct comparison with the provided Ki in the dataset. 
%[text] First, the integral of the IDIF at the last eight frames are calculated using the trapezoidal integration technique.
i = size(sub000IDIFdata.("Frame Time Middle [s]"),1);
a = sub000IDIFdata.("Frame Time Middle [s]");
b = sub000IDIFdata.("PET Mean [Bq/mL]");
IDIFTIAC = cumtrapz(a,b);
%%
%[text] ## Estimating Ki for the brain
PatlakY = brainTACdata.("PET Mean [Bq/mL]")(end-7:end)./sub000IDIFdata.("PET Mean [Bq/mL]")(end-7:end);
PatlakX = IDIFTIAC(end-7:end)./sub000IDIFdata.("PET Mean [Bq/mL]")(end-7:end);
coeffs = polyfit(PatlakX,PatlakY,1);
measuredbrainKi = coeffs(1);
%%
%[text] ## Estimating Ki for the spleen
PatlakY = spleenTACdata.("PET Mean [Bq/mL]")(end-7:end)./sub000IDIFdata.("PET Mean [Bq/mL]")(end-7:end);
PatlakX = IDIFTIAC(end-7:end)./sub000IDIFdata.("PET Mean [Bq/mL]")(end-7:end);
coeffs = polyfit(PatlakX,PatlakY,1);
measuredspleenKi = coeffs(1);
%%
%[text] ## Validation of results
%[text] To validate results, the estimated net influx rates and the ones provided in the dataset are compared.
errorBrain = ((measuredbrainKi-truebrainKi)/truebrainKi);
errorSpleen = ((measuredspleenKi-truespleenKi)/truebrainKi);
errors = [errorBrain;errorSpleen];

ROI = ["Brain"; "Spleen"];
True_Ki = [truebrainKi; truespleenKi];
Measured_Ki = [measuredbrainKi; measuredspleenKi];
errors = [errorBrain; errorSpleen];

T = table(ROI, True_Ki, Measured_Ki, errors, ...
    VariableNames = ["ROI", "True Ki", "Measured Ki", "% Error"]);

fig = uifigure('Position', [100 100 500 140]); %[output:650d411c]

gl = uigridlayout(fig, [2 1]); %[output:650d411c]
gl.Padding = [0 0 0 0]; %[output:650d411c]
gl.RowSpacing = 0; %[output:650d411c]
gl.ColumnSpacing = 0; %[output:650d411c]
gl.RowHeight = {'fit', 'fit'}; %[output:650d411c]

uit = uitable(gl, 'Data', T); %[output:650d411c]
uit.Layout.Row = 1; %[output:650d411c]
uit.Layout.Column = 1; %[output:650d411c]
uit.FontSize = 14; %[output:650d411c]

lbl = uilabel(gl, ... %[output:650d411c]
    'Text', 'The measured and true Patlak Ki are in excellent agreement.', ... %[output:650d411c]
    'HorizontalAlignment', 'center', ... %[output:650d411c]
    'FontSize', 16); %[output:650d411c]
lbl.Layout.Row = 2; %[output:650d411c]
lbl.Layout.Column = 1; %[output:650d411c]

